use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_lattice_world_v1::{world,Admission},native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),80);let v:Vec<u32>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();let mut out=Vec::new();for c in v.chunks_exact(5){let origin=[f32::from_bits(c[1]),f32::from_bits(c[2]),f32::from_bits(c[3])];for x in world(c[0],origin,f32::from_bits(c[4]),Policy::Mxcsr1f80,Admission).unwrap(){out.extend(x.to_bits().to_le_bytes());}}io::stdout().write_all(&out).unwrap();}
